'use client';
import Link from 'next/link';import {Menu,X} from 'lucide-react';import {useState} from 'react';import {nav,t} from '@/lib/content';import {useLanguage} from './LanguageProvider';import {FederationLogo} from './FederationLogo';
export function Header(){const{lang,setLang}=useLanguage(),[open,setOpen]=useState(false);return <header className="sticky top-0 z-50 border-b border-white/10 bg-[#0a241df5] text-white backdrop-blur"><div className="container flex h-[4.75rem] items-center justify-between gap-4 sm:h-20"><Link href="/" className="flex min-w-0 items-center gap-2.5 sm:gap-3" aria-label={t(lang,'GeOF — მთავარი გვერდი','GeOF — home')}><FederationLogo variant="header" priority/><span className="min-w-0 leading-tight"><b className="block truncate text-[15px] sm:text-base">GeOF</b><small className="block truncate text-[10px] tracking-[.14em] text-white/60 sm:tracking-[.18em]">{t(lang,'საქართველოს ორიენტირება','Orienteering Georgia')}</small></span></Link><nav className="desktop flex items-center gap-5 text-[13px] font-semibold">{nav.map(n=><Link key={n[0]} className="hover:text-orange-400" href={n[0]}>{t(lang,n[1],n[2])}</Link>)}</nav><div className="flex items-center gap-3"><button className="text-xs font-bold" onClick={()=>setLang(lang==='ka'?'en':'ka')} aria-label="Switch language">{lang==='ka'?'ქართული | ENG':'KA | English'}</button><button className="mobile" onClick={()=>setOpen(!open)} aria-label="Menu">{open?<X/>:<Menu/>}</button></div></div>{open&&<nav className="mobile container grid gap-1 pb-5">{nav.map(n=><Link onClick={()=>setOpen(false)} className="rounded-lg px-3 py-2 hover:bg-white/10" key={n[0]} href={n[0]}>{t(lang,n[1],n[2])}</Link>)}</nav>}</header>}
